mapper.select:
SELECT d.id, d.employee_id, d.document_type, d.title
FROM archive_document d JOIN employee e ON e.id = d.employee_id
WHERE 1 = 1
AND d.employee_id = #{employeeId}

ORDER BY d.updated_at DESC, d.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM archive_document d JOIN employee e ON e.id = d.employee_id
WHERE 1 = 1
AND d.employee_id = #{employeeId}

SELECT COUNT(*) FROM archive_version v JOIN archive_document d ON d.id = v.document_id
JOIN employee e ON e.id = d.employee_id
WHERE v.document_id = #{documentId}

SELECT id, employee_id, document_type, title
FROM archive_document WHERE employee_id = #{employeeId} AND document_type = #{documentType}
LIMIT 1 FOR UPDATE

SELECT v.id, v.document_id, v.version_no, v.file_object_id, v.original_name, v.content_type, v.byte_size, v.sha256, v.status, v.is_current, v.created_at, v.created_by, v.change_reason, d.employee_id FROM archive_version v JOIN archive_document d ON d.id = v.document_id JOIN employee e ON e.id = d.employee_id WHERE v.id = #{versionId}
AND 1 = 1 AND e.department_id = #{departmentId} AND e.id = #{employeeId} AND 1 = 0
LIMIT 1

SELECT v.id AS version_id, f.object_key, v.original_name, v.content_type, v.byte_size, v.sha256, d.document_type, e.id AS employee_id, e.department_id, v.created_by FROM archive_version v JOIN archive_document d ON d.id = v.document_id JOIN file_object f ON f.id = v.file_object_id JOIN employee e ON e.id = d.employee_id WHERE v.id = #{versionId}
AND 1 = 1 AND e.department_id = #{departmentId} AND e.id = #{employeeId} AND 1 = 0
LIMIT 1
